import { useCallback, useMemo, useState } from 'react';

import { noop } from 'lodash';
import { useIntl } from 'react-intl';
import { StyleSheet } from 'react-native';

import {
  Button,
  Dialog,
  Icon,
  SizableText,
  Toast,
  YStack,
} from '@onekeyhq/components';
import { ListItem } from '@onekeyhq/kit/src/components/ListItem';
import useAppNavigation from '@onekeyhq/kit/src/hooks/useAppNavigation';
import {
  onboardingCloudBackupListRefreshAtom,
  useOnboardingCloudBackupListRefreshAtom,
} from '@onekeyhq/kit-bg/src/states/jotai/atoms';
import type {
  IBackupDataManifest,
  IBackupDataManifestItem,
} from '@onekeyhq/shared/src/cloudBackup/cloudBackupTypes';
import { ETranslations } from '@onekeyhq/shared/src/locale';
import platformEnv from '@onekeyhq/shared/src/platformEnv';
import type { IOnboardingParamListV2 } from '@onekeyhq/shared/src/routes';
import {
  ECloudBackupRoutes,
  EModalRoutes,
  EOnboardingPagesV2,
} from '@onekeyhq/shared/src/routes';
import { formatDate } from '@onekeyhq/shared/src/utils/dateUtils';
import timerUtils from '@onekeyhq/shared/src/utils/timerUtils';

import backgroundApiProxy from '../../../background/instance/backgroundApiProxy';
import { MultipleClickStack } from '../../../components/MultipleClickStack';
import { useAppRoute } from '../../../hooks/useAppRoute';
import { usePromiseResult } from '../../../hooks/usePromiseResult';
import { CloudAccountBar } from '../components/CloudAccountBar';
import { showCloudBackupPasswordDialog } from '../components/CloudBackupDialogs';
import { CloudBackupListEmptyView } from '../components/CloudBackupEmptyView';
import { CloudBackupLoadingSkeleton } from '../components/CloudBackupLoadingSkeleton';
import { KeylessWalletBackupInfo } from '../components/KeylessWalletBackupInfo';
import { OnboardingPage } from '../components/Layout';
import { useCloudBackup } from '../hooks/useCloudBackup';
import { OnboardingTestIDs } from '../testIDs';

export default function ICloudBackup() {
  const navigation = useAppNavigation();
  const [refreshHook] = useOnboardingCloudBackupListRefreshAtom();
  const intl = useIntl();
  const route = useAppRoute<
    IOnboardingParamListV2,
    EOnboardingPagesV2.ICloudBackup
  >();
  const hideRestoreButton = route?.params?.hideRestoreButton;
  const { startBackup } = useCloudBackup();

  const { result: legacyBackups } = usePromiseResult(async () => {
    if (platformEnv.isNative) {
      return backgroundApiProxy.serviceCloudBackup.getMetaDataFromCloud();
    }
    return null;
  }, []);

  const { result: allBackupsFromCloud, isLoading } = usePromiseResult(
    async () => {
      await timerUtils.wait(300);
      noop(refreshHook);
      return backgroundApiProxy.serviceCloudBackupV2.getAllBackups();
    },
    [refreshHook],
    {
      watchLoading: true,
    },
  );
  const [allBackupsMocked, setAllBackupsMocked] = useState<
    IBackupDataManifest | undefined
  >(undefined);

  const allBackups = useMemo(() => {
    return allBackupsMocked ?? allBackupsFromCloud;
  }, [allBackupsMocked, allBackupsFromCloud]);

  const handleBackupPress = useCallback(
    (item: IBackupDataManifestItem) => {
      const params: IOnboardingParamListV2[EOnboardingPagesV2.ICloudBackupDetails] =
        {
          backupTime: item.dataTime,
          backupId: item.recordID,
          actionType: 'restore',
          hideRestoreButton,
        };
      navigation.push(EOnboardingPagesV2.ICloudBackupDetails, params);
    },
    [navigation, hideRestoreButton],
  );

  const renderContent = () => {
    if (isLoading) {
      return <CloudBackupLoadingSkeleton />;
    }

    if (!allBackups?.items?.length) {
      return (
        <YStack flex={1} justifyContent="center">
          <CloudBackupListEmptyView />
        </YStack>
      );
    }

    return (
      <>
        {allBackups?.items?.map((item, index) => (
          <ListItem
            key={`${item.dataTime}-${index}`}
            gap="$3"
            bg="$bg"
            $platform-web={{
              boxShadow:
                '0 0 0 1px rgba(0, 0, 0, 0.04), 0 0 2px 0 rgba(0, 0, 0, 0.08), 0 1px 2px 0 rgba(0, 0, 0, 0.06)',
            }}
            $theme-dark={{
              borderWidth: StyleSheet.hairlineWidth,
              borderColor: '$neutral3',
            }}
            $platform-native={{
              borderWidth: StyleSheet.hairlineWidth,
              borderColor: '$borderSubdued',
            }}
            borderRadius="$5"
            borderCurve="continuous"
            py="$3"
            px="$5"
            m="$0"
            onPress={() => handleBackupPress(item)}
            userSelect="none"
          >
            <YStack gap={2} flex={1}>
              <SizableText
                size="$bodyMdMedium"
                $platform-native={{
                  size: '$bodyLgMedium',
                }}
              >
                {item.dataTime
                  ? formatDate(new Date(item.dataTime), { hideSeconds: true })
                  : 'ERROR: Invalid Backup'}
              </SizableText>
              <SizableText
                color="$textSubdued"
                $platform-native={{
                  size: '$bodyMd',
                }}
              >
                {intl.formatMessage(
                  { id: ETranslations.global_count_wallets },
                  { count: item.totalWalletsCount },
                )}
                {', '}
                {intl.formatMessage(
                  { id: ETranslations.global_count_accounts },
                  { count: item.totalAccountsCount },
                )}
              </SizableText>
            </YStack>
            <Icon name="ChevronRightSmallOutline" color="$iconDisabled" />
          </ListItem>
        ))}
      </>
    );
  };

  const showLegacyBackupsButton =
    Boolean(legacyBackups?.length) && !hideRestoreButton;

  const handleOpenLegacyBackups = useCallback(() => {
    navigation?.pushModal(EModalRoutes.CloudBackupModal, {
      screen: ECloudBackupRoutes.CloudBackupHome,
    });
  }, [navigation]);

  const title =
    platformEnv.isNativeIOS || platformEnv.isDesktopMac
      ? intl.formatMessage({ id: ETranslations.settings_icloud_backup })
      : intl.formatMessage({ id: ETranslations.settings_google_drive_backup });

  return (
    <OnboardingPage
      testID={OnboardingTestIDs.iCloudBackupPage}
      safeAreaEnabled={false}
      scrollable
      headerTitle={title}
      contentContainerProps={{ maxWidth: 480, gap: '$3', paddingVertical: 20 }}
    >
      <CloudAccountBar />
      <YStack flex={1} gap="$3">
        {renderContent()}
        {showLegacyBackupsButton ? (
          <Button
            testID={OnboardingTestIDs.iCloudBackupViewOlderBackupsBtn}
            size="large"
            onPress={handleOpenLegacyBackups}
          >
            {intl.formatMessage({ id: ETranslations.view_older_backups })}
          </Button>
        ) : null}
        <KeylessWalletBackupInfo />
      </YStack>

      <MultipleClickStack
        h="$10"
        showDevBgColor
        debugComponent={
          <YStack gap="$2">
            <SizableText>备份数：{allBackups?.items?.length}</SizableText>
            <Button
              testID={OnboardingTestIDs.iCloudBackupDevMockEmptyBtn}
              onPress={async () => {
                setAllBackupsMocked({
                  items: [],
                  total: 0,
                  backupPasswordVerify: undefined,
                });
              }}
            >
              Mock Empty Backups
            </Button>
            <Button
              testID={OnboardingTestIDs.iCloudBackupDevClearPasswordBtn}
              variant="destructive"
              onPress={async () => {
                Dialog.show({
                  title: 'Clear Backup Password',
                  description:
                    'This will permanently delete the backup password from the cloud.',
                  onConfirm: async () => {
                    await backgroundApiProxy.serviceCloudBackupV2.clearBackupPassword();
                  },
                });
              }}
            >
              clearBackupPassword
            </Button>
            <Button
              testID={OnboardingTestIDs.iCloudBackupDevIsPasswordSetBtn}
              onPress={async () =>
                Dialog.debugMessage({
                  debugMessage:
                    await backgroundApiProxy.serviceCloudBackupV2.isBackupPasswordSet(),
                })
              }
            >
              isBackupPasswordSet
            </Button>
            <Button
              testID={OnboardingTestIDs.iCloudBackupDevVerifyPasswordBtn}
              onPress={async () =>
                showCloudBackupPasswordDialog({
                  intl,
                  onSubmit: async (password) => {
                    const result =
                      await backgroundApiProxy.serviceCloudBackupV2.verifyBackupPassword(
                        {
                          password,
                        },
                      );
                    Dialog.debugMessage({
                      debugMessage: result,
                    });
                  },
                })
              }
            >
              verifyBackupPassword
            </Button>
            <Button
              testID={OnboardingTestIDs.iCloudBackupDevSetPasswordBtn}
              onPress={async () => {
                showCloudBackupPasswordDialog({
                  intl,
                  onSubmit: async (password) => {
                    const result =
                      await backgroundApiProxy.serviceCloudBackupV2.setBackupPassword(
                        {
                          password,
                        },
                      );
                    Dialog.debugMessage({
                      debugMessage: result,
                    });
                  },
                });
              }}
            >
              setBackupPassword
            </Button>

            <Button
              testID={OnboardingTestIDs.iCloudBackupDevGetAllBackupsBtn}
              onPress={async () =>
                Dialog.debugMessage({
                  debugMessage:
                    await backgroundApiProxy.serviceCloudBackupV2.getAllBackups(),
                })
              }
            >
              getAllBackups
            </Button>
            <Button
              testID={OnboardingTestIDs.iCloudBackupDevIOSQueryAllRecordsBtn}
              onPress={async () =>
                Dialog.debugMessage({
                  debugMessage:
                    await backgroundApiProxy.serviceCloudBackupV2.iOSQueryAllRecords(),
                })
              }
            >
              iOSQueryAllRecords
            </Button>
            <Button
              testID={OnboardingTestIDs.iCloudBackupDevAndroidListAllFilesBtn}
              onPress={async () =>
                Dialog.debugMessage({
                  debugMessage:
                    await backgroundApiProxy.serviceCloudBackupV2.androidListAllFiles(),
                })
              }
            >
              androidListAllFiles
            </Button>
            <Button
              testID={OnboardingTestIDs.iCloudBackupDevAndroidGetManifestBtn}
              onPress={async () =>
                Dialog.debugMessage({
                  debugMessage:
                    await backgroundApiProxy.serviceCloudBackupV2.androidGetManifest(),
                })
              }
            >
              androidGetManifest
            </Button>
            <Button
              testID={
                OnboardingTestIDs.iCloudBackupDevAndroidGetLegacyMetaDataBtn
              }
              onPress={async () =>
                Dialog.debugMessage({
                  debugMessage:
                    await backgroundApiProxy.serviceCloudBackupV2.androidGetLegacyMetaData(),
                })
              }
            >
              androidGetLegacyMetaData
            </Button>
            <Button
              testID={
                OnboardingTestIDs.iCloudBackupDevAndroidGetManifestFileObjectBtn
              }
              onPress={async () =>
                Dialog.debugMessage({
                  debugMessage:
                    await backgroundApiProxy.serviceCloudBackupV2.androidGetManifestFileObject(),
                })
              }
            >
              androidGetManifestFileObject
            </Button>
            <Button
              testID={
                OnboardingTestIDs.iCloudBackupDevAndroidRemoveManifestFileBtn
              }
              variant="destructive"
              onPress={async () => {
                Dialog.show({
                  title: 'remove manifest file',
                  description:
                    'This will permanently delete the manifest file from the cloud.',
                  onConfirm: async () => {
                    Dialog.debugMessage({
                      debugMessage:
                        await backgroundApiProxy.serviceCloudBackupV2.androidRemoveManifestFile(),
                    });
                  },
                });
              }}
            >
              androidRemoveManifestFile
            </Button>
            <Button
              testID={OnboardingTestIDs.iCloudBackupDevBackupNowToDetailBtn}
              onPress={async () => {
                await startBackup({
                  alwaysGoToBackupDetail: true,
                });
              }}
            >
              BackupNow(ToDetailPage)
            </Button>
            <Button
              testID={OnboardingTestIDs.iCloudBackupDevBackupNowBtn}
              onPress={async () => {
                await startBackup();
              }}
            >
              BackupNow
            </Button>
            <Button
              testID={OnboardingTestIDs.iCloudBackupDevGetCloudAccountInfoBtn}
              onPress={async () => {
                const info =
                  await backgroundApiProxy.serviceCloudBackupV2.getCloudAccountInfo();
                Dialog.debugMessage({
                  debugMessage: info,
                });
              }}
            >
              GetCloudAccountInfo
            </Button>
            <Button
              testID={OnboardingTestIDs.iCloudBackupDevRemoveAllBackupsBtn}
              variant="destructive"
              onPress={async () => {
                const data =
                  await backgroundApiProxy.serviceCloudBackupV2.getAllBackups();
                const items = data?.items ?? [];
                if (!items.length) {
                  Toast.success({
                    title: 'No backups to delete',
                  });
                  return;
                }
                Dialog.show({
                  icon: 'DeleteOutline',
                  tone: 'destructive',
                  title: 'Delete all backups?',
                  description:
                    "This will permanently delete all backups from iCloud. Make sure you've saved Recovery phrases, otherwise you won't be able to restore the wallets.",
                  onConfirmText: 'Delete',
                  confirmButtonProps: {
                    variant: 'destructive',
                  },
                  onCancelText: 'Cancel',
                  onConfirm: async () => {
                    const result =
                      await backgroundApiProxy.serviceCloudBackupV2.deleteAllBackups();
                    await onboardingCloudBackupListRefreshAtom.set(
                      (v) => v + 1,
                    );
                    if (result.failedCount) {
                      Toast.error({
                        title: 'Some backups could not be deleted',
                      });
                    } else {
                      Toast.success({
                        title: 'All backups deleted',
                      });
                    }
                  },
                });
              }}
            >
              Remove All Backups
            </Button>
            <Button
              testID={OnboardingTestIDs.iCloudBackupDevOpenLegacyBackupsBtn}
              onPress={handleOpenLegacyBackups}
            >
              {intl.formatMessage({
                id: ETranslations.view_older_backups,
              })}
            </Button>
          </YStack>
        }
      />
    </OnboardingPage>
  );
}
